import { createHash } from 'node:crypto';
import {
  existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync,
} from 'node:fs';
import { resolve } from 'node:path';
import { defineConfig, type Plugin, type ServerOptions } from 'vite';

/*
 * Development serving.
 *
 * By default the dev server binds to 127.0.0.1 over plain HTTP: the only origin a
 * phone or another machine can reach is localhost, and localhost is a secure context,
 * so WebUSB works for whoever runs the browser on this machine.
 *
 * `LOGICWEB_LAN=1` (the `dev:lan` / `preview:lan` scripts) binds every interface so a
 * phone on the same Wi-Fi can open the page. WebUSB refuses to exist outside a secure
 * context, and a bare LAN IP over HTTP is not one, so LAN mode serves HTTPS from the
 * self-signed pair in certs/ (generated by `npm run cert`). The phone must accept the
 * certificate warning once; after that https://<lan-ip>:5173 is a secure context and
 * `navigator.usb` is present, so a logic analyser plugged into the phone (Android
 * Chrome, USB-C/OTG) is usable. Testing only the responsive layout needs no device.
 */
function lanServer(port: number): ServerOptions {
  if (process.env.LOGICWEB_LAN !== '1') return { host: '127.0.0.1', port };
  const key = resolve(__dirname, 'certs/dev-key.pem');
  const cert = resolve(__dirname, 'certs/dev-cert.pem');
  if (!existsSync(key) || !existsSync(cert)) {
    throw new Error(
      'LOGICWEB_LAN=1 needs a TLS certificate for the secure context WebUSB requires.\n' +
      'Run `npm run cert` to generate certs/dev-{key,cert}.pem, then retry.');
  }
  return {
    host: '0.0.0.0',
    port,
    https: { key: readFileSync(key), cert: readFileSync(cert) },
  };
}

function hostedWorkerFiles(): Plugin {
  return {
    name: 'logicweb:hosted-worker-files',
    apply: 'build',
    enforce: 'pre',
    resolveId(source, importer) {
      if (portable || !importer || !source.endsWith('?worker&inline')) return null;
      return this.resolve(source.replace(/\?worker&inline$/, '?worker'), importer, { skipSelf: true });
    },
  };
}

function serveUiControlEntry(): Plugin {
  return {
    name: 'logicweb:uictrl-entry',
    apply: 'serve',
    configureServer(server) {
      server.middlewares.use((request, _response, next) => {
        const url = request.url;
        if (url === '/uictrl') request.url = '/uictrl/';
        else if (url?.startsWith('/uictrl?')) {
          request.url = `/uictrl/${url.slice('/uictrl'.length)}`;
        }
        next();
      });
    },
  };
}

/*
 * Fail the build when a run-time asset is missing, rather than shipping a bundle that
 * looks fine and 404s on first use.
 *
 * `public/pyodide/` and `public/decoders/` are gitignored - they are vendored by
 * `npm run vendor` - so a fresh clone would otherwise build something that dies on the
 * first decode with no hint as to why.
 *
 * The two licence texts are checked for the same reason, one step removed: without them
 * the build still runs perfectly, and ships MPL-2.0 and PSF code with no notice
 * attached. A silent licensing defect is worse than a loud missing file.
 */
function requireRuntimeAssets(): Plugin {
  return {
    name: 'logicweb:runtime-assets',
    apply: 'build',
    buildStart() {
      const required = [
        ['public/pyodide', 'the Pyodide runtime'],
        ['public/decoders', 'the sigrok decoder tree'],
        ['public/pyodide/LICENSE-pyodide-MPL-2.0.txt', "Pyodide's licence"],
        ['public/pyodide/LICENSE-cpython-PSF.txt', "the embedded CPython's licence"],
      ] as const;
      const missing = required
        .filter(([p]) => !existsSync(resolve(__dirname, p)))
        .map(([p, what]) => `  ${p}  (${what})`);
      if (missing.length > 0) {
        this.error(
          `the build would 404 at run time, missing:\n${missing.join('\n')}\n` +
          `Run \`npm run vendor -- <libsigrokdecode/decoders>\`.`);
      }
    },
  };
}

/*
 * Content-hashed paths for the two run-time assets the page fetches by a fixed name.
 *
 * slogic.sipeed.com sits behind a CDN that keeps files for weeks and allows only a few
 * folder purges a day, but hundreds of single-URL purges. Everything else the page loads
 * already has a content hash in its name (Vite's [name]-[hash] chunks) or is inlined
 * into index.html, so once these two carry one as well, purging index.html alone updates
 * the whole site: a changed file gets a new URL the CDN has never cached.
 *
 *   public/pyodide/*            -> dist/pyodide/<hash>/*    (Pyodide builds the .wasm,
 *                                   stdlib and lock-file URLs from its indexURL, so the
 *                                   version has to be a directory, not a ?v= query)
 *   public/decoders/decoders.zip -> dist/decoders/decoders-<hash>.zip
 *
 * The paths reach the code as __LOGICWEB_RUNTIME_PATHS__ (app.ts, decode/worker.ts).
 * Hosted builds only: the dev server serves public/ as-is, and the portable build embeds
 * both assets in index.html.
 */
const PLAIN_RUNTIME_PATHS = { pyodide: 'pyodide/', decoders: 'decoders/decoders.zip' };

function contentHash(paths: readonly string[]): string {
  const h = createHash('sha256');
  for (const p of paths) {
    h.update(p.slice(p.lastIndexOf('/') + 1));
    h.update(readFileSync(p));
  }
  return h.digest('hex').slice(0, 10);
}

function versionRuntimeAssets(): Plugin {
  let paths = PLAIN_RUNTIME_PATHS;
  return {
    name: 'logicweb:version-runtime-assets',
    config(_config, env) {
      const pyDir = resolve(__dirname, 'public/pyodide');
      const zip = resolve(__dirname, 'public/decoders/decoders.zip');
      // Missing assets are requireRuntimeAssets' error to report; keep plain paths here.
      if (env.command === 'build' && !portable && existsSync(pyDir) && existsSync(zip)) {
        const pyFiles = readdirSync(pyDir).sort().map((f) => resolve(pyDir, f))
          .filter((f) => statSync(f).isFile());
        paths = {
          pyodide: `pyodide/${contentHash(pyFiles)}/`,
          decoders: `decoders/decoders-${contentHash([zip])}.zip`,
        };
      }
      return { define: { __LOGICWEB_RUNTIME_PATHS__: JSON.stringify(paths) } };
    },
    closeBundle() {
      if (paths === PLAIN_RUNTIME_PATHS) return;
      const out = resolve(__dirname, 'dist');
      const pyDir = resolve(out, 'pyodide');
      const versioned = resolve(out, paths.pyodide);
      if (!existsSync(versioned)) {
        mkdirSync(versioned, { recursive: true });
        for (const f of readdirSync(pyDir)) {
          const from = resolve(pyDir, f);
          if (statSync(from).isFile()) renameSync(from, resolve(versioned, f));
        }
      }
      const zip = resolve(out, 'decoders/decoders.zip');
      if (existsSync(zip)) renameSync(zip, resolve(out, paths.decoders));
      if (!existsSync(resolve(versioned, 'pyodide.asm.wasm')) || !existsSync(resolve(out, paths.decoders))) {
        this.error(`versioned runtime assets are incomplete: ${paths.pyodide}, ${paths.decoders}`);
      }
    },
  };
}

/*
 * Put this project's own GPLv3 text in the published tree.
 *
 * GPLv3 section 6 wants the corresponding source offered to whoever receives the object
 * code, and the banner on each chunk points at the repository - but a deployment that
 * carries the licence itself needs no argument about whether a link is enough. It also
 * covers the bundled decoders, which are GPL and ship their per-file headers inside
 * decoders.zip but not the licence body.
 */
/*
 * The AI assistant's Claude client and the packages it pulls into the bundle (checked
 * against the build's source maps; see NOTICE.md). All permissive and GPL-compatible.
 * standardwebhooks ships no licence file on npm, so its upstream text is committed under
 * licenses/, as Pyodide's is.
 */
const ASSISTANT_LICENSES: readonly [string, string][] = [
  ['@anthropic-ai/sdk (Apache-2.0)', 'node_modules/@anthropic-ai/sdk/LICENSE'],
  ['@anthropic-ai/sdk, contributions before 1.0 (MIT)', 'node_modules/@anthropic-ai/sdk/LICENSE-MIT'],
  ['@opentelemetry/api (Apache-2.0)', 'node_modules/@opentelemetry/api/LICENSE'],
  ['standardwebhooks (MIT)', 'licenses/standardwebhooks-LICENSE.txt'],
  ['@stablelib/base64 (MIT)', 'node_modules/@stablelib/base64/LICENSE'],
  ['fast-sha256 (Unlicense)', 'node_modules/fast-sha256/LICENSE'],
];

function emitLicense(): Plugin {
  return {
    name: 'logicweb:emit-license',
    apply: 'build',
    generateBundle() {
      this.emitFile({
        type: 'asset',
        fileName: 'LICENSE.txt',
        source: readFileSync(resolve(__dirname, 'LICENSE'), 'utf8'),
      });
      this.emitFile({
        type: 'asset',
        fileName: 'THIRD_PARTY_LICENSES.txt',
        source:
          'Pyodide\n=======\n\n' +
          readFileSync(resolve(__dirname, 'public/pyodide/LICENSE-pyodide-MPL-2.0.txt'), 'utf8') +
          '\n\nCPython embedded by Pyodide\n===========================\n\n' +
          readFileSync(resolve(__dirname, 'public/pyodide/LICENSE-cpython-PSF.txt'), 'utf8') +
          ASSISTANT_LICENSES.map(([name, path]) =>
            `\n\n${name}\n${'='.repeat(name.length)}\n\n${readFileSync(resolve(__dirname, path), 'utf8')}`).join(''),
      });
      this.emitFile({
        type: 'asset',
        fileName: 'DEPLOY.txt',
        source: portable
          ? 'logicweb static distribution\n\n' +
            'index.html contains the UI, Decode Worker, Pyodide WASM/stdlib and sigrok decoders.\n' +
            'Double-click it for capture, WebUSB, protocol decoding and the Advanced USB console.\n' +
            'Node, npm and a local HTTP server are not runtime dependencies.\n' +
            'It can also be served unchanged from any static HTTPS host.\n' +
            'JavaScript source maps are included for browser debugging. Advanced contains the USB console.\n'
          : 'logicweb static distribution\n\n' +
            'index.html inlines the application code and styles; the Decode and USB workers,\n' +
            'the decoder detail data, Pyodide WASM/stdlib and the sigrok decoders ship as\n' +
            'separate files beside it. Serve this directory unchanged from any static HTTPS\n' +
            'host - Node and npm are not runtime dependencies. The entry source map is inlined\n' +
            'for browser debugging; other maps ship beside their files. Advanced contains the\n' +
            'USB console.\n\n' +
            'Double-clicking index.html still opens the UI and capture works through the\n' +
            'in-page USB fallback, but the workers and the decoder detail data cannot load\n' +
            'from file://, so protocol decoding needs the portable single-file build instead.\n',
      });
    },
  };
}

/**
 * Keep normal hashed assets/source maps, but also inline the entry JS and CSS into
 * dist/index.html. The portable build also bundles the decode worker and all of its
 * runtime data, so the result does not perform a neighbouring file:// import or fetch.
 */
function inlineEntryForFileOpen(): Plugin {
  return {
    name: 'logicweb:inline-entry-for-file-open',
    apply: 'build',
    enforce: 'post',
    closeBundle() {
      const out = resolve(__dirname, 'dist');
      const indexPath = resolve(out, 'index.html');
      let html = readFileSync(indexPath, 'utf8');
      html = html.replace(
        /<script\s+type="module"[^>]*\ssrc="([^"]+)"[^>]*><\/script>/,
        (_tag, src: string) => {
          const rel = src.replace(/^\.\//, '').replace(/^\//, '');
          let code = readFileSync(resolve(out, rel), 'utf8');
          const dir = rel.includes('/') ? rel.slice(0, rel.lastIndexOf('/') + 1) : '';
          // Both the entry and the inline worker carry source map comments. Put the
          // maps in data URLs so moving index.html alone keeps TypeScript debugging.
          code = code.replace(
            /\/\/# sourceMappingURL=([A-Za-z0-9_./-]+\.map)/g,
            (_comment, map: string) => {
              const mapPath = resolve(
                out, dir, map.replace(/^\.\//, '').replace(/^\//, ''));
              return `//# sourceMappingURL=data:application/json;base64,${
                readFileSync(mapPath).toString('base64')}`;
            },
          );
          code = code.replace(
            /new URL\("([^"./][^"]*?\.js)",(\s*)import\.meta\.url\)/g,
            'new URL("assets/$1",$2import.meta.url)',
          );
          code = code.replace(/<\/script/gi, '<\\/script');
          return `<script type="module">\n${code}\n</script>`;
        },
      );
      html = html.replace(
        /<link\s+rel="stylesheet"[^>]*\shref="([^"]+)"[^>]*>/,
        (_tag, href: string) => {
          const rel = href.replace(/^\.\//, '').replace(/^\//, '');
          return `<style>\n${readFileSync(resolve(out, rel), 'utf8')}\n</style>`;
        },
      );
      html = html.replace(
        /<link\s+rel="icon"[^>]*>/,
        `<link rel="icon" type="image/svg+xml" href="data:image/svg+xml;base64,${
          readFileSync(resolve(out, 'favicon.svg')).toString('base64')}">`,
      );
      const stray = html.match(/new URL\("(?!assets\/)[^"]+\.js"/);
      if (stray) this.error(`inlined entry has an unresolved worker URL: ${stray[0]}`);
      for (const m of html.matchAll(/new URL\("assets\/([^"]+\.js)"/g)) {
        if (!existsSync(resolve(out, 'assets', m[1]))) {
          this.error(`inlined entry references missing asset ${m[1]}`);
        }
      }

      writeFileSync(indexPath, html);

      if (portable) {
        // All executable/runtime files and source maps are now represented inside
        // index.html. Leave only documentation/licences beside the portable app.
        for (const rel of ['assets', 'pyodide', 'decoders', 'favicon.svg', '.nojekyll']) {
          const generated = resolve(out, rel);
          if (existsSync(generated)) rmSync(generated, { recursive: true });
        }
      }
    },
  };
}

/*
 * Every source file carries an SPDX header, but the minifier strips comments, so the
 * built bundles would otherwise reach users with no licence notice at all - which is
 * the one thing the GPL is actually about. Re-attach it to each emitted chunk.
 */
const BANNER =
  '/*! SPDX-License-Identifier: GPL-3.0-or-later\n' +
  ' * logicweb - Copyright (C) 2026 Daniel Tralamazza\n' +
  ' * Free software with NO WARRANTY, under GNU GPL v3 or later.\n' +
  ' * Source: https://github.com/tralamazza/logicweb\n' +
  ' */';

const portable = process.env.LOGICWEB_PORTABLE === '1';
const portableAssets = portable ? {
  pyodideMjs: readFileSync(resolve(__dirname, 'public/pyodide/pyodide.mjs')).toString('base64'),
  pyodideAsmMjs: readFileSync(resolve(__dirname, 'public/pyodide/pyodide.asm.mjs')).toString('base64'),
  pyodideWasm: readFileSync(resolve(__dirname, 'public/pyodide/pyodide.asm.wasm')).toString('base64'),
  stdlibZip: readFileSync(resolve(__dirname, 'public/pyodide/python_stdlib.zip')).toString('base64'),
  lockJson: readFileSync(resolve(__dirname, 'public/pyodide/pyodide-lock.json')).toString('base64'),
  decodersZip: readFileSync(resolve(__dirname, 'public/decoders/decoders.zip')).toString('base64'),
} : null;

export default defineConfig({
  // Asset URLs remain portable when dist/ is hosted below a path. The entry itself is
  // inlined after build so it also works from file://.
  base: './',
  server: lanServer(5173),
  preview: lanServer(5174),

  define: {
    __LOGICWEB_PORTABLE_ASSETS__: JSON.stringify(portableAssets),
  },

  /*
   * Bundle the inline decode worker as one classic script. A file:// document's
   * opaque origin cannot start a module Blob worker in Chromium; a classic Blob
   * worker can. Vite folds the worker's static TypeScript imports into this IIFE,
   * while Pyodide's run-time blob modules continue to use dynamic import().
   */
  worker: {
    format: 'iife',
    rollupOptions: { output: { banner: BANNER } },
  },

  build: {
    // Keep production minification while making the exact TypeScript sources available
    // in DevTools when diagnosing USB/decoder issues on a user's machine.
    sourcemap: true,
    chunkSizeWarningLimit: portable ? 20_000 : 2048,
    rollupOptions: {
      output: {
        banner: BANNER,
        // The inlineEntryForFileOpen plugin inlines the entry script into
        // dist/index.html in EVERY build, so a relative dynamic-import
        // specifier resolves against the document URL, not against assets/.
        // Locale chunks must therefore sit at the dist root: emitted under the
        // default assets/[name]-[hash].js they would be requested from
        // <origin-root>/<chunk>.js and 404. Today the locale catalogs are the only
        // dynamic imports, so nothing else lands at the root for this reason.
        // Caveat: rollup renders the specifier relative to the entry chunk, so it
        // is emitted as "../<chunk>.js". That resolves correctly for the deployments
        // that work today (dist/ at the origin root; the live --base=/ custom-domain
        // build) but escapes the base when dist/ is hosted below a sub-path. Fixing
        // sub-path hosting is a separate, coordinated change (the plugin must become
        // base-aware - it currently crashes on a sub-path base even without this
        // commit - plus co-located entry/chunks and matching worker map placement).
        chunkFileNames: '[name]-[hash].js',
        // The portable build inlines the entry into index.html, deletes every
        // sibling executable file, and is opened over file:// - where a
        // separate chunk import cannot work. Folding dynamic imports back into
        // the entry keeps the single-file artifact intact and self-contained.
        ...(portable ? { inlineDynamicImports: true } : {
          // The assistant's Claude client (src/assistant/providers/claude.ts) is a lazy
          // chunk whose SDK has dynamic imports of its own, which Vite wraps in its
          // preload helper. Left to rollup, that helper lands in the entry, so the chunk
          // would import the entry asset - and evaluating the entry starts a second App
          // (the 0340d7a failure). A chunk of its own keeps the helper import-free and
          // shared. tools/assistant-selftest.ts checks the built chunks for this.
          manualChunks: (id: string) => (id.includes('vite/preload-helper') ? 'preload-helper' : undefined),
        }),
      },
    },
  },

  plugins: [
    serveUiControlEntry(), requireRuntimeAssets(), versionRuntimeAssets(), emitLicense(),
    inlineEntryForFileOpen(), hostedWorkerFiles(),
  ],
});
